insert into public.guion_pasos (id, nombre, hace) values ('G', 'Gancho', 'La primera frase: una afirmación con emoción fuerte, con número o con escenario. Nunca saluda.') on conflict (id) do update set nombre = excluded.nombre, hace = excluded.hace, activa = true;
insert into public.guion_pasos (id, nombre, hace) values ('D', 'Descarte', 'Tacha lo que el público ya cree que funciona, nombrando creencias concretas (nunca un eslogan abstracto). Así lo que viene suena nuevo.') on conflict (id) do update set nombre = excluded.nombre, hace = excluded.hace, activa = true;
insert into public.guion_pasos (id, nombre, hace) values ('A', 'Aplazamiento', 'Anuncia que hay una cosa que importa y no la dice todavía: la frase se corta, señala sin nombrar o promete que viene después. Es un open loop.') on conflict (id) do update set nombre = excluded.nombre, hace = excluded.hace, activa = true;
insert into public.guion_pasos (id, nombre, hace) values ('C', 'Credencial', 'Una prueba con cifra: la propia, o la de un cliente o caso ajeno. El nombre de quien habla va aquí, nunca en el gancho.') on conflict (id) do update set nombre = excluded.nombre, hace = excluded.hace, activa = true;
insert into public.guion_pasos (id, nombre, hace) values ('K', 'Concepto con nombre', 'La idea recibe un nombre propio corto que dice lo que es («el grupito de prueba», «la regla de los tres segundos») y se explica con un ejemplo que se ve. Letras solo si salen solas y no hay que explicarlas. Es lo que la gente recuerda y comenta.') on conflict (id) do update set nombre = excluded.nombre, hace = excluded.hace, activa = true;
insert into public.guion_pasos (id, nombre, hace) values ('E', 'Explicación', 'Un ejemplo con números redondos o con algo que se ve: primero el caso malo, luego el bueno. Nunca teoría.') on conflict (id) do update set nombre = excluded.nombre, hace = excluded.hace, activa = true;
insert into public.guion_pasos (id, nombre, hace) values ('B', 'Objeción', 'Alguien dice en voz alta lo que piensa el público («¿cómo que al revés?») y eso abre la parte siguiente.') on conflict (id) do update set nombre = excluded.nombre, hace = excluded.hace, activa = true;
insert into public.guion_pasos (id, nombre, hace) values ('P', 'Pregunta puente', 'Deja la idea incompleta a propósito: lo enseñado no sirve si no sabes cómo hacer la parte difícil. Solo el llamado a la acción la completa.') on conflict (id) do update set nombre = excluded.nombre, hace = excluded.hace, activa = true;
insert into public.guion_pasos (id, nombre, hace) values ('O', 'Llamado a la acción', 'Pide comentar una palabra clave, explica por qué esa palabra si es rara, promete algo para el caso concreto de quien mira, señala pruebas («como este, este o este») y cierra repitiendo la palabra.') on conflict (id) do update set nombre = excluded.nombre, hace = excluded.hace, activa = true;
insert into public.guion_pasos (id, nombre, hace) values ('R', 'Remate', 'Un chiste o una frase de otro personaje después del llamado a la acción. Opcional.') on conflict (id) do update set nombre = excluded.nombre, hace = excluded.hace, activa = true;
insert into public.guion_plantillas (id, nombre, resumen, orden, respaldo, pasos, pantalla) values ('sigla', 'La sigla', 'Le pones un nombre propio corto a tu idea, uno que diga lo que es («el grupito de prueba»), y la explicas con un ejemplo que se ve. Lo mejor es grabarla en un sitio que sea la metáfora de la idea.', 1, '{"videos": 6, "creadores": 1, "vistas": 1976000, "mejor": 639505}'::jsonb, '[{"p": "G", "donde": [0, 7]}, {"p": "D", "donde": [5, 15], "opcional": true}, {"p": "A", "donde": [10, 20], "loop": true}, {"p": "C", "donde": [15, 30]}, {"p": "K", "donde": [20, 35]}, {"p": "E", "donde": [35, 75]}, {"p": "P", "donde": [70, 82], "loop": true}, {"p": "O", "donde": [80, 100]}, {"p": "R", "donde": [96, 100], "opcional": true}]'::jsonb, '["El nombre del concepto se arma en pantalla y queda a la vista mientras explicas.", "Tus videos o los de tus clientes flotando con su número cuando dices la credencial.", "Un escenario que cuenta la idea (hielo, un triángulo pintado en el piso, una piscina que se llena).", "La caja de comentarios escribiendo la palabra clave al final."]'::jsonb) on conflict (id) do update set nombre = excluded.nombre, resumen = excluded.resumen, orden = excluded.orden, respaldo = excluded.respaldo, pasos = excluded.pasos, pantalla = excluded.pantalla, activa = true, actualizado = now();
insert into public.guion_plantillas (id, nombre, resumen, orden, respaldo, pasos, pantalla) values ('lista', 'La lista con trampa', 'Anuncias un número de cosas (errores, ajustes, cambios, pasos) y las cuentas. La última no es un consejo más: es lo que ofreces, o la pregunta que solo tu oferta contesta.', 2, '{"videos": 4, "creadores": 1, "vistas": 556525, "mejor": 232804}'::jsonb, '[{"p": "G", "donde": [0, 8]}, {"p": "E", "donde": [5, 45]}, {"p": "C", "donde": [15, 60]}, {"p": "A", "donde": [35, 55], "loop": true}, {"p": "E", "donde": [45, 75]}, {"p": "P", "donde": [70, 85], "loop": true}, {"p": "O", "donde": [80, 100]}]'::jsonb, '["Un contador en la esquina (1/3, 2/3, 3/3) o el número gigante de cada punto.", "El último punto tapado con un signo de interrogación hasta que llega.", "La caja de comentarios escribiendo la palabra clave al final."]'::jsonb) on conflict (id) do update set nombre = excluded.nombre, resumen = excluded.resumen, orden = excluded.orden, respaldo = excluded.respaldo, pasos = excluded.pasos, pantalla = excluded.pantalla, activa = true, actualizado = now();
insert into public.guion_plantillas (id, nombre, resumen, orden, respaldo, pasos, pantalla) values ('sketch', 'El sketch', 'Una escena actuada entre dos personajes (médico y paciente, jefe y empleado). El que no sabe pone en voz alta las dudas del público, y cada duda abre la parte siguiente.', 3, '{"videos": 1, "creadores": 1, "vistas": 86368, "mejor": 86368}'::jsonb, '[{"p": "G", "donde": [0, 8]}, {"p": "E", "donde": [8, 25]}, {"p": "B", "donde": [20, 40], "loop": true}, {"p": "K", "donde": [35, 55]}, {"p": "C", "donde": [55, 75]}, {"p": "P", "donde": [72, 80], "loop": true}, {"p": "O", "donde": [78, 98]}, {"p": "R", "donde": [97, 100], "opcional": true}]'::jsonb, '["Dos personajes con vestuario que se reconoce de un vistazo (bata, uniforme).", "Las respuestas del que sabe, con un dato o un gráfico al lado.", "Las pruebas como fichas (tarjetas de perfil de los casos)."]'::jsonb) on conflict (id) do update set nombre = excluded.nombre, resumen = excluded.resumen, orden = excluded.orden, respaldo = excluded.respaldo, pasos = excluded.pasos, pantalla = excluded.pantalla, activa = true, actualizado = now();
insert into public.guion_plantillas (id, nombre, resumen, orden, respaldo, pasos, pantalla) values ('casa_ajena', 'El ejemplo en casa ajena', 'Enseñas tu método aplicado en un negocio que no es el tuyo (una pizzería, una peluquería) mientras trabajas ahí. Cualquiera se reconoce, sea de lo que sea.', 4, '{"videos": 1, "creadores": 1, "vistas": 515107, "mejor": 515107}'::jsonb, '[{"p": "G", "donde": [0, 6]}, {"p": "E", "donde": [5, 40]}, {"p": "C", "donde": [38, 58]}, {"p": "K", "donde": [55, 80]}, {"p": "O", "donde": [80, 100]}]'::jsonb, '["Tú haciendo el trabajo del sitio (amasando, cortando pelo) mientras explicas.", "La gente real del sitio contestando algo.", "Números grandes de las pruebas y la palabra clave al final."]'::jsonb) on conflict (id) do update set nombre = excluded.nombre, resumen = excluded.resumen, orden = excluded.orden, respaldo = excluded.respaldo, pasos = excluded.pasos, pantalla = excluded.pantalla, activa = true, actualizado = now();
insert into public.guion_ganchos (id, nombre, orden, emocion, molde, ejemplo, ve, respaldo) values ('contra', 'La contra', 1, 'rabia', '[Algo que todos creen, dicho como si fuera verdad]. [Una palabra que lo tumba].', 'Crecer en Instagram es demasiado fácil. Y una mierda.', 'Corte seco en la palabra que lo tumba, y esa palabra gigante.', 2) on conflict (id) do update set nombre = excluded.nombre, orden = excluded.orden, emocion = excluded.emocion, molde = excluded.molde, ejemplo = excluded.ejemplo, ve = excluded.ve, respaldo = excluded.respaldo, activa = true, actualizado = now();
insert into public.guion_ganchos (id, nombre, orden, emocion, molde, ejemplo, ve, respaldo) values ('cebo', 'El cebo interrumpido', 2, 'sorpresa', 'Dices [lo que todos creen o buscan] y algo o alguien te interrumpe dejando claro que es una tontería. Luego arrancas: «Mira…».', 'La mejor hora para publicar en Instagram es… (blanco y negro, suspiro) Mira, he publicado videos a las dos de la mañana…', 'La interrupción se VE: pasa un carro, alguien te calla, la imagen pasa a blanco y negro, te agarras la cabeza.', 4) on conflict (id) do update set nombre = excluded.nombre, orden = excluded.orden, emocion = excluded.emocion, molde = excluded.molde, ejemplo = excluded.ejemplo, ve = excluded.ve, respaldo = excluded.respaldo, activa = true, actualizado = now();
insert into public.guion_ganchos (id, nombre, orden, emocion, molde, ejemplo, ve, respaldo) values ('hipotetico', 'El hipotético', 3, 'curiosidad', 'Si mañana [empezara de cero en lo tuyo], esto es exactamente lo que haría para [resultado grande] antes de [plazo].', 'Si mañana me despertara con cero seguidores, esto es exactamente lo que haría para crecer 100.000 antes de fin de año.', 'Una escena que muestra el «desde cero»: despertándote, la cuenta en cero.', 1) on conflict (id) do update set nombre = excluded.nombre, orden = excluded.orden, emocion = excluded.emocion, molde = excluded.molde, ejemplo = excluded.ejemplo, ve = excluded.ve, respaldo = excluded.respaldo, activa = true, actualizado = now();
insert into public.guion_ganchos (id, nombre, orden, emocion, molde, ejemplo, ve, respaldo) values ('resultado', 'El resultado imposible', 4, 'curiosidad', 'Este [video o acción pequeña] me [consiguió algo enorme], y así fue exactamente como lo hice.', 'Este video con 100.000 visitas me pagó esta casa, y así fue exactamente como lo hice.', 'Lo enorme en pantalla (la casa, la cifra) junto a lo pequeño que lo logró.', 1) on conflict (id) do update set nombre = excluded.nombre, orden = excluded.orden, emocion = excluded.emocion, molde = excluded.molde, ejemplo = excluded.ejemplo, ve = excluded.ve, respaldo = excluded.respaldo, activa = true, actualizado = now();
insert into public.guion_ganchos (id, nombre, orden, emocion, molde, ejemplo, ve, respaldo) values ('cambio', 'El cambio', 5, 'miedo', '[Algo de tu sector] acaba de cambiar, y lo que funcionaba antes ya no funciona.', 'El algoritmo de Instagram acaba de cambiar en septiembre, y lo que funcionaba antes ya no funciona.', 'Un lugar grande o una pantalla que marque «nuevo».', 2) on conflict (id) do update set nombre = excluded.nombre, orden = excluded.orden, emocion = excluded.emocion, molde = excluded.molde, ejemplo = excluded.ejemplo, ve = excluded.ve, respaldo = excluded.respaldo, activa = true, actualizado = now();
insert into public.guion_ganchos (id, nombre, orden, emocion, molde, ejemplo, ve, respaldo) values ('orden', 'La orden', 6, 'miedo', 'No [hagas lo de siempre] hasta que no hagas estos [3] ajustes.', 'No publiques más en Instagram hasta que no hagas estos tres ajustes.', 'El número gigante y tú frenando algo con la mano.', 1) on conflict (id) do update set nombre = excluded.nombre, orden = excluded.orden, emocion = excluded.emocion, molde = excluded.molde, ejemplo = excluded.ejemplo, ve = excluded.ve, respaldo = excluded.respaldo, activa = true, actualizado = now();
insert into public.guion_ganchos (id, nombre, orden, emocion, molde, ejemplo, ve, respaldo) values ('lista', 'La lista', 7, 'curiosidad', 'Estos son los [7] [errores] que no te dejan [meta], y estos [3] son los más fáciles de corregir.', 'Estos son los siete errores que no dejan crecer tu cuenta, y estos tres son los más fáciles de corregir.', 'Una hoja o tablero con los puntos numerados, tapados.', 1) on conflict (id) do update set nombre = excluded.nombre, orden = excluded.orden, emocion = excluded.emocion, molde = excluded.molde, ejemplo = excluded.ejemplo, ve = excluded.ve, respaldo = excluded.respaldo, activa = true, actualizado = now();
insert into public.guion_ganchos (id, nombre, orden, emocion, molde, ejemplo, ve, respaldo) values ('niega', 'Lo que se ve lo niega', 8, 'sorpresa', 'Para [meta] no hace falta [lo extremo que estás haciendo en cámara].', 'Para crecer en Instagram no hace falta meterse en una piscina con 150 kilos de hielo.', 'Estás haciendo justo eso tan extremo mientras lo dices.', 1) on conflict (id) do update set nombre = excluded.nombre, orden = excluded.orden, emocion = excluded.emocion, molde = excluded.molde, ejemplo = excluded.ejemplo, ve = excluded.ve, respaldo = excluded.respaldo, activa = true, actualizado = now();
insert into public.guion_ganchos (id, nombre, orden, emocion, molde, ejemplo, ve, respaldo) values ('pregunta', 'La pregunta de todos', 9, 'curiosidad', '¿Cómo diablos hace la gente para [lo que el público no logra]?', '¿Cómo diablos hace la gente para hacer guiones virales?', 'Rodeado de lo que sale mal (papeles arrugados, vistas bajas).', 1) on conflict (id) do update set nombre = excluded.nombre, orden = excluded.orden, emocion = excluded.emocion, molde = excluded.molde, ejemplo = excluded.ejemplo, ve = excluded.ve, respaldo = excluded.respaldo, activa = true, actualizado = now();
insert into public.guion_ganchos (id, nombre, orden, emocion, molde, ejemplo, ve, respaldo) values ('diagnostico', 'El diagnóstico', 10, 'miedo', 'Tu [cuenta, negocio, cuerpo] está muy mal. (y el otro personaje:) ¿Qué? No, eso no puede ser. Yo [lo que cree hacer bien].', 'Su cuenta de Instagram está muy jodida. — ¿Qué? No puede ser. Yo subo dos videos al día.', 'Una escena que se reconoce: consultorio, taller, oficina.', 1) on conflict (id) do update set nombre = excluded.nombre, orden = excluded.orden, emocion = excluded.emocion, molde = excluded.molde, ejemplo = excluded.ejemplo, ve = excluded.ve, respaldo = excluded.respaldo, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h10', 'sigla', 'hipotetico', 69, 166158, '[["G", "Si mañana [empezara de cero en lo tuyo], esto es exactamente lo que haría para [resultado grande] antes de [plazo]."], ["D", "Y no, no te voy a hablar de [creencia 1], ni de [creencia 2], ni de [creencia 3]."], ["A", "Te hablo de algo mucho más simple, y de hecho es lo único que importa para [meta]."], ["C", "Y este concepto me ha hecho [credencial con cifra] para mí y para mis clientes, solamente con [método]."], ["K", "Y este es el concepto de [NOMBRE CORTO DE LA IDEA, que diga lo que es], que es la relación entre [cosa A] y [cosa B]."], ["E", "Si [ejemplo con número: se lo muestran a mil] y solamente [a cien les funciona], [resultado malo], porque [cifra mala]. Pero si [el mismo caso: a los mismos mil] y [a ochocientos les funciona], [cifra buena], y por lo tanto [resultado bueno]."], ["P", "Y la verdad es que todo esto no sirve de nada si no sabes cómo conseguir [la parte difícil]."], ["O", "Y justamente para eso, si pones aquí abajo la palabra [PALABRA], que es [por qué esa palabra], vas a ver exactamente cómo [promesa] y cómo te puede ayudar a conseguir resultados como este, este o este. Escribe en comentarios la palabra [PALABRA] para saber cómo hacerlo en tu caso en concreto."]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h11', 'sigla', 'niega', 58, 621440, '[["G", "Para [meta] no hace falta [algo extremo que estás haciendo en cámara] ni que [detalle extremo]."], ["A", "Lo que hace falta es entender este concepto."], ["C", "Concepto que me ha hecho [credencial con cifra] para mí y para mis clientes."], ["K", "Y ese es el concepto del [NOMBRE CORTO DE LA IDEA, que diga lo que es]."], ["E", "Fíjate en [objeto del escenario]: para que [fenómeno] hace falta que [condición] sea muy, muy [extremo]. Y no son [valor cercano], no son [otro valor cercano], aunque [parezca suficiente]: son [valor exacto]. ¡[Reacción de otra persona]! Con [tu tema] pasa lo mismo, pero con [la idea]. Fíjate que [lo que el espectador acaba de hacer] hasta llegar a mi video. ¿Por qué? Porque te generé [la idea]."], ["C", "Y para que tú [meta] tienes que hacer lo mismo que hice con este cliente, con este cliente o con este cliente, que entre todos suman [cifra]."], ["O", "Y si tú quieres por fin [meta], envíame la palabra [PALABRA] y te voy a decir exactamente cómo [promesa] para tu caso en concreto. Por aquí la palabra [PALABRA]."]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h05', 'sigla', 'cebo', 107, 639505, '[["G", "[Algo de tu sector] acaba de [novedad] que va a hacerte [beneficio], siempre y cuando sepas cómo usarla. Estoy hablando de [lo que todos comentan]."], ["D", "No, no necesitas más trucos para [meta], sino un método. Pero esta vez un método de verdad. Lo primero es olvidarte de esa mentira de que [creencia popular], porque como tú mismo habrás comprobado, eso no funciona."], ["C", "Soy [tu nombre]. En [año] logré [credencial con cifra] usando el [NOMBRE CORTO DE LA IDEA, que diga lo que es]."], ["A", "Para que [resultado] tienen que cumplirse tres cosas. Fíjate bien, porque esta última es la más importante, la que sostiene todo, y sin ella nada va a funcionar."], ["E", "Da exactamente igual que [algo increíble que podrías ofrecer] si absolutamente nadie se para a escucharte. Lo primero, sí o sí: [cosa 1, en palabras simples], para que [efecto]. Pero siempre teniendo en cuenta lo segundo: [cosa 2]. [Quien decide] es una empresa y lo único que le importa es [su interés]. ¿Y cómo consigue eso? Con [respuesta]. Exacto, con [respuesta]. Cuanto más [X], más [Y]. [Quien decide] te va a recomendar siempre y cuando… siempre y cuando [cosa 2 bien hecha]."], ["P", "Pero esto no sirve de nada sin lo tercero: [cosa 3]."], ["O", "Que vas a usar para [promesa], como esta, esta o esta, que te traiga [clientes] para tu negocio. Y eso mismo lo voy a hacer yo personalmente contigo. En [tu oferta] voy a [lo que recibe] para que [resultado]. Escribe en comentarios la palabra [PALABRA] para apuntarte, y comenzamos [cuándo]."]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h07', 'sigla', 'contra', 79, 311099, '[["G", "[Meta] es demasiado fácil. Y una mierda."], ["C", "He [resultado 1 con cifra] en [tiempo 1]. Y [resultado 2 con cifra] en [tiempo 2]."], ["A", "Y lo único que he hecho es…"], ["C", "¡Ey! Soy [tu nombre] y he [credencial con cifra]."], ["A", "Y te puedo asegurar que lo único que importa para [meta] es el concepto del [NOMBRE CORTO DE LA IDEA, que diga lo que es]."], ["K", "Fíjate en este [figura u objeto]. No, así no. Gíralo un poco más. Ahí. En [un extremo] va a estar [lo muy concreto], y si abrimos arriba tenemos [lo muy general], como podría ser [ejemplos]."], ["E", "Para [meta] tienes que hacer [algo] de [tu tema], ni muy [extremo 1], que sería [dónde], ni muy [extremo 2], porque sería [consecuencia], sino en el punto medio, y a eso le llamamos el [NOMBRE CORTO DE LA IDEA, que diga lo que es]."], ["C", "Esta es una parte del método con el que he hecho [credencial con cifra]."], ["O", "Y si quieres aplicar exactamente esta metodología en tu [caso], pon en comentarios la palabra [PALABRA]."], ["R", "¿Por qué [PALABRA]? Porque [explicación absurda de la palabra]. Pon en comentarios [PALABRA]."]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h01', 'sigla', 'pregunta', 88, 141235, '[["G", "¿Cómo diablos hace la gente para [lo que el público no logra]?"], ["K", "Así: con el método [NOMBRE CORTO DE LA IDEA, que diga lo que es]."], ["E", "[Lo primero, con nombre simple]. No hay nada que una persona quiera ver más que [algo que siente]. Cuando alguien [lo siente], esa emoción se repite en su cabeza una y otra vez. Por eso, [algo] que empieza desde [palabra 1] no solo llama la atención: obsesiona."], ["E", "[Lo segundo, con nombre simple]. Ahora viene la parte que nadie quiere. A nadie le gusta [x]. Ni [ejemplo 1 en voz del público]. Ni [ejemplo 2]. Ni [ejemplo 3]."], ["A", "Por eso, justo después de [paso anterior], tienes que hacer algo clave."], ["E", "[La acción clave]. Tienes que decirle: oye, [frase]. Y ahí, en ese momento, [efecto]. [Lo tercero, con nombre simple]. [Definición que sorprende]."], ["P", "Y en ese punto siempre sale una pregunta: bueno, pero entonces, ¿qué sí tengo que hacer?"], ["O", "Para eso, si comentas la palabra [PALABRA], te voy a explicar [tu oferta exacta] para [resultado 1] y [resultado 2]. Comenta en este video [PALABRA] y te lo explico paso a paso por mensaje directo para tu caso."]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h06', 'sigla', 'resultado', 69, 99055, '[["G", "Este [video o acción pequeña] me [consiguió algo enorme], y así fue exactamente como lo hice."], ["A", "Lo primero que hice fue [acción concreta 1] para [propósito]. Aquí encontré una [NOMBRE CORTO DE LA IDEA, que diga lo que es]."], ["K", "Es el [significado de la sigla], y con eso hice [algo] solucionando ese problema."], ["B", "¿Y cómo lo hiciste [resultado]? Buena pregunta. Con esta [estructura o método]."], ["E", "[El método en una frase simple]. [Cómo se hace: dos o tres pasos concretos de ESTE tema]. ¿Por qué? Porque lo más importante para que [resultado] es [la razón]."], ["C", "[Lo que consiguió con esto: su credencial real; si no la hay, se deja el hueco]."], ["O", "Así que para saber cómo aplicar este método en tu caso en concreto, pon aquí la palabra [PALABRA]."]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h03', 'lista', 'lista', 115, 178043, '[["G", "Estos son los [N] [errores] que no te dejan [meta], y estos [3] son los más fáciles de corregir. Cuando los corrijas, [resultado]."], ["E", "Error número [N], que todo el mundo comete: [error], pensando que [creencia]. Error número [N-1]: [error]. Al [hacerlo] pasan dos cosas: uno, [consecuencia 1], y dos, [consecuencia 2]. Error número [N-2]: [error]. [Por qué es un error]. Error número [N-3]: [error]. Sí, es el más sencillo y el más rápido, pero también es el que más gente hace."], ["A", "Entramos al top tres, comenzando por [error 3]."], ["C", "Siempre pensamos en [lo que se cree], cuando lo que realmente hay que hacer es [lo correcto], como esta de mi cliente, que tiene [cifra] y fue la [n] vez que lo hicimos."], ["E", "Error número dos: [error]. [Explicación con contraste]. Cuanto más [simple], más [resultado]."], ["P", "Y error número uno, el principal, el más común y el que más te está frenando:"], ["O", "no estar en [tu oferta] de [cuándo], en la que te voy a explicar exactamente cómo [promesa], con todo el método con el que he hecho [credencial con cifra]. Comenta [PALABRA] en este video para apuntarte, y te veo [cuándo]. Comenta [PALABRA] en este video."]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h04', 'lista', 'orden', 99, 105107, '[["G", "No [hagas lo de siempre] más hasta que no hagas estos tres ajustes en tu [cosa]."], ["E", "El primero es [ajuste 1] y quitar todas esas [cosas que todos hacen]: «[ejemplo en voz del público]…», «[otro ejemplo]…». ¡Cállense la boca ya! Eso es como decir [lo que de verdad comunica]."], ["C", "Mira lo mío: [credencial con cifra]."], ["E", "[La razón por la que eso que todos dicen no sirve]. La segunda es [ajuste 2]. [Una aclaración corta que se adelanta a la queja del público]. Vas a [acción medible, paso a paso], y esto te dará [el dato con nombre]. Lo tercero: vas a usar [el dato] para ver [diagnóstico]. Porque puede ser que [problema oculto], y déjame decirte que si no [meta], es probablemente por eso. Y para que eso no pase, todo tiene que partir de [lo difícil]."], ["P", "Pero la pregunta aquí es: ¿cómo se consigue [lo difícil]? Pues la verdad es que es difícil de verdad."], ["O", "Por eso [cuándo] voy a [tu oferta], en la que te voy a mostrar cómo [promesa]. Para apuntarte, solo comenta [PALABRA] en este video. Solo si quieres [meta] de verdad; si no, no hagas nada."]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h09', 'lista', 'cambio', 73, 232804, '[["G", "[Algo de tu sector] acaba de cambiar [cuándo], y lo que funcionaba [antes] ya no funciona."], ["D", "Y no cambió una sola cosa: cambiaron una, dos y tres."], ["E", "Uno: [algo que se creía bueno] puede ser algo malo. Antes, [cómo era]. Pero ahora, [cómo es] si [condición]. A esto se le llama [nombre]. Dos: antes [proporción], y ahora es exactamente al revés: [proporción invertida]. Tres: antes había que [mucho de algo], y ahora solamente con [uno bueno] vas a [resultado]."], ["C", "¿Por qué? Porque en [tu experiencia reciente con clientes] me di cuenta de que [dato]. O sea, que [conclusión]. Mejor [uno bueno] que [siete normales]."], ["P", "Y la pregunta ahora es cómo vas a hacer tú, en tu [caso] en concreto, para [resultado], como este cliente, este cliente o este cliente."], ["O", "Pon aquí la palabra [PALABRA] y te voy a decir exactamente cómo tienes que hacerlo con esta metodología para [promesa]. Así que pon aquí [PALABRA]."]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h12', 'lista', 'cebo', 102, 40571, '[["G", "[La respuesta que todos buscan] está muy cerca de [su opuesto], y ten cuidado, porque como te equivoques, [consecuencia]."], ["C", "Después de [credencial con cifra], te puedo decir que [la respuesta que todos buscan] es…"], ["E", "Mira, [anécdota que contradice la creencia]. ¿Por qué? Porque [la razón de verdad], y eso se basa en cuatro pasos simples. Lo primero es [paso 1], para que [efecto], como en este video o como en este video. Lo segundo es [paso 2] con [ingredientes]; esto va a hacer que [efecto]. Lo tercero sería [paso 3], que te posiciona como [experto en lo tuyo]. Y lo cuarto es [paso 4]."], ["P", "Seguramente esto ya lo sabías, y la pregunta aquí es: ¿por qué no te está funcionando, si sabes cómo hacerlo? Porque [la causa de fondo] no es correcta, aunque sigas estos pasos. Y la pregunta es: ¿cómo consigo [la causa de fondo bien hecha]?"], ["O", "Tengo [un recurso] que de momento ha visto poca gente, en el que te explico exactamente cómo [promesa]. Pon en comentarios la palabra [PALABRA] y te lo mando para que lo veas antes de que lo borre, porque ahí te lo explico todo."]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h02', 'sketch', 'diagnostico', 78, 86368, '[["G", "Su [cuenta, negocio o cuerpo] está muy mal. ¿Qué? No, eso no puede ser. Yo [lo que cree hacer bien]."], ["E", "Empezando por su [indicador], que se ve así. ¿Y eso por qué pasa? Porque le dedica el [80] % del esfuerzo a [lo que se cree], cuando debería ser al revés."], ["B", "¿Cómo que al revés? Lo más importante es [la creencia]. No: el [80] % del esfuerzo tiene que ir en [lo real]. Eso significa que todo depende de [eso]. Sí, pero… ¿cómo?"], ["K", "Porque después de [paso 1] viene el [NOMBRE CORTO DE LA IDEA, que diga lo que es]. ¿Qué? Es el [significado]: la relación entre [cosa A] y [cosa B]. Si eso sale mal, [consecuencia con la metáfora de la escena], como está usted ahora mismo."], ["C", "¿Pero tiene cura? Sí. Por ejemplo, mi paciente [nombre] llegó con [antes] y hoy tiene [después]. O mi paciente [nombre], que llegó con [problema] y hoy tiene [después]."], ["P", "Doctor, yo quiero saber eso para mi [caso]. Creo que eso lo vemos en la próxima consulta."], ["O", "Si comentas [PALABRA] en este video, la agendamos y tenemos [tu oferta] contigo para explicarte cómo [promesa]. Comenta [PALABRA] en este video y te agendo."], ["R", "¿[Remate corto del paciente]?"]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
insert into public.guion_calcos (id, plantilla, gancho, dur, vistas, tramos) values ('h08', 'casa_ajena', 'resultado', 56, 515107, '[["G", "Así puedes [resultado] en [cualquier negocio o situación]."], ["E", "Lo primero es [paso 1]. Y en [este negocio ajeno], lo más [curioso] es [cosa 1]. ¿[Pregunta 2]? ¿Y [pregunta 3]? [Respuesta real de alguien del sitio]. Una vez hagas eso, vas a [paso 2] en todos los [formatos o maneras] que existen: [ejemplo 1], [ejemplo 2], [ejemplo 3]."], ["C", "Esto me ha generado [credencial con cifra], con [pruebas] como este, como este o como este que estás viendo ahora mismo."], ["K", "Y para eso vas a hacer tu [trabajo] como [lo que vende este negocio], que le gusta a todo el mundo: [la idea principal del método, con un ejemplo de este negocio]."], ["O", "Y si estás cansado de [problema], pon aquí la palabra [PALABRA] y te voy a decir exactamente cómo [promesa], y cómo conseguir [resultados] como este, este o este. Pon aquí [PALABRA]."]]'::jsonb) on conflict (id) do update set plantilla = excluded.plantilla, gancho = excluded.gancho, dur = excluded.dur, vistas = excluded.vistas, tramos = excluded.tramos, activa = true, actualizado = now();
